Arguments: {"title":"Test trial extraction function on NCT05918783","code":"const tabId = 787784140;

const trialData = await browserjs(tabId, () => {
  // Extract title
  let title = '';
  const titleParts = document.title.split('|');
  if (titleParts.length >= 3) {
    title = titleParts[2].trim();
  } else {
    title = document.querySelector('h1')?.innerText?.trim() || document.title;
  }

  // Also get official title if available
  const fullText = document.body.innerText;
  const officialTitleMatch = fullText.match(/Official Title\s*\n\s*([^\n]+)/i);
  const officialTitle = officialTitleMatch ? officialTitleMatch[1].trim() : '';

  // Status
  let status = 'Not Found';
  if (fullText.includes('Recruiting') && !fullText.includes('Not yet recruiting')) {
    status = 'Recruiting';
  } else if (fullText.includes('Recruiting')) {
    status = 'Recruiting';
  }

  // Phase
  const phaseMatch = fullText.match(/Phase\s*\n\s*(Phase\s*[1-4](?:\/[1-4])?|Early Phase 1|Phase Not Applicable|Not Applicable)/i) ||
                     fullText.match(/Phases\s*\n\s*([^\n]+)/i) ||
                     fullText.match(/(Phase\s*[1-4](?:\/[1-4])?|Early Phase 1)/i);
  const phase = phaseMatch ? phaseMatch[1].trim() : 'N/A';

  // Interventions
  // Extract Intervention/Treatment block from overview
  let interventions = [];
  const intrMatch = fullText.match(/Intervention\/Treatment\s*\n([\s\S]*?)(?:Other Study ID Numbers|Study Start|Resource links)/i);
  if (intrMatch) {
    interventions = intrMatch[1].split('\n').map(s => s.trim()).filter(s => s.length > 0 && !s.startsWith('Click to'));
  }

  // Locations
  // Extract from Contacts and Locations section
  const locSection = document.querySelector('#contacts-and-locations')?.innerText || '';
  const usLocMatch = locSection.match(/United States([\s\S]*?)(?:Click to view interactive map|Participation Criteria|Collaborators and Investigators|$)/i);
  let locations = [];
  if (usLocMatch) {
    const locLines = usLocMatch[1].split('\n').map(s => s.trim()).filter(s => s.length > 0 && !s.includes('Recruiting') && !s.includes('Contact :') && !s.includes('Locations') && !s.includes('Principal Investigator') && !s.includes('Sub-Investigator'));
    locations = locLines.slice(0, 15);
  }

  return {
    title: title || officialTitle,
    officialTitle,
    status,
    phase,
    interventions: interventions.join('; '),
    locations: locations.join('; '),
    url: window.location.href.split('?')[0]
  };
});

